#!/bin/bash
# Uninstall script for Real VNC Server
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Real VNC Server..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Real VNC Server if running..."
pkill -f "Real VNC Server" 2>/dev/null || true

# Unload service com.realvnc.vncagent.peruser
echo "Unloading service com.realvnc.vncagent.peruser..."
launchctl unload -w /Library/LaunchAgents/com.realvnc.vncagent.peruser.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.realvnc.vncagent.peruser.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.realvnc.vncagent.peruser.plist 2>/dev/null || true

# Unload service com.realvnc.vncagent.prelogin
echo "Unloading service com.realvnc.vncagent.prelogin..."
launchctl unload -w /Library/LaunchAgents/com.realvnc.vncagent.prelogin.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.realvnc.vncagent.prelogin.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.realvnc.vncagent.prelogin.plist 2>/dev/null || true

# Unload service com.realvnc.vncserver
echo "Unloading service com.realvnc.vncserver..."
launchctl unload -w /Library/LaunchAgents/com.realvnc.vncserver.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.realvnc.vncserver.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.realvnc.vncserver.plist 2>/dev/null || true

# Unload service com.realvnc.vncserver.peruser
echo "Unloading service com.realvnc.vncserver.peruser..."
launchctl unload -w /Library/LaunchAgents/com.realvnc.vncserver.peruser.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.realvnc.vncserver.peruser.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.realvnc.vncserver.peruser.plist 2>/dev/null || true

# Remove /Library/Logs/vncserver.log.bak
echo "Removing /Library/Logs/vncserver.log.bak..."
if [ -d "/Library/Logs/vncserver.log.bak" ]; then
    rm -rf "/Library/Logs/vncserver.log.bak" 2>/dev/null || true
elif [ -f "/Library/Logs/vncserver.log.bak" ]; then
    rm -f "/Library/Logs/vncserver.log.bak" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.realvnc.vnclicensewiz.savedState
echo "Removing $HOME/Library/Saved Application State/com.realvnc.vnclicensewiz.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.realvnc.vnclicensewiz.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.realvnc.vnclicensewiz.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.realvnc.vnclicensewiz.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.realvnc.vnclicensewiz.savedState" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.realvnc.vncserver.savedState
echo "Removing $HOME/Library/Saved Application State/com.realvnc.vncserver.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.realvnc.vncserver.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.realvnc.vncserver.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.realvnc.vncserver.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.realvnc.vncserver.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
